/**
 * Sets the active view. Calls deactivate on the previously
 * active view, and then calls activate on the given view.
 *
 * @param newValue
 * 		Active view, can be null.
 */
public void setActiveView(View newValue) {
    View oldValue = activeView;
    if ((activeView) != null) {
        activeView.deactivate();
    }
    activeView = newValue;
    if ((activeView) != null) {
        activeView.activate();
    }
    firePropertyChange(Application.ACTIVE_VIEW_PROPERTY, oldValue, newValue);
}

public void remove(View p) {
    hide(p);
    int oldCount = views.size();
    views.remove(p);
    p.setApplication(null);
    firePropertyChange(AbstractApplication.VIEW_COUNT_PROPERTY, oldCount, views.size());
}

public void add(View p) {
    if ((p.getApplication()) != (this)) {
        int oldCount = views.size();
        views.add(p);
        p.setApplication(this);
        firePropertyChange(AbstractApplication.VIEW_COUNT_PROPERTY, oldCount, views.size());
    }
}

public void dispose(View p) {
    remove(p);
    p.dispose();
}

