public void show(final View p) {
    if (!(p.isShowing())) {
        p.setShowing(true);
        final JFrame f = new JFrame();
        f.setDefaultCloseOperation(JFrame.DO_NOTHING_ON_CLOSE);
        updateViewTitle(p, f);
        JPanel panel = ((JPanel) (wrapViewComponent(p)));
        f.add(panel);
        f.setMinimumSize(new Dimension(200, 200));
        f.setPreferredSize(new Dimension(600, 400));
        f.setJMenuBar(createMenuBar(p, ((List<Action>) (panel.getClientProperty("toolBarActions")))));
        PreferencesUtil.installFramePrefsHandler(prefs, "view", f);
        Point loc = f.getLocation();
        boolean moved;
        do {
            moved = false;
            for (Iterator i = views().iterator(); i.hasNext();) {
                View aView = ((View) (i.next()));
                if (((aView != p) && ((SwingUtilities.getWindowAncestor(aView.getComponent())) != null)) && (SwingUtilities.getWindowAncestor(aView.getComponent()).getLocation().equals(loc))) {
                    loc.x += 22;
                    loc.y += 22;
                    moved = true;
                    break;
                }
            }
        } while (moved );
        f.setLocation(loc);
        f.addWindowListener(new WindowAdapter() {
            public void windowClosing(final WindowEvent evt) {
                getModel().getAction(CloseAction.ID).actionPerformed(new ActionEvent(f, ActionEvent.ACTION_PERFORMED, "windowClosing"));
            }

            @Override
            public void windowClosed(final WindowEvent evt) {
                if (p == (getActiveView())) {
                    setActiveView(null);
                }
                p.stop();
            }

            public void windowActivated(WindowEvent e) {
                setActiveView(p);
            }
        });
        p.addPropertyChangeListener(new PropertyChangeListener() {
            public void propertyChange(PropertyChangeEvent evt) {
                String name = evt.getPropertyName();
                if (((name.equals(View.HAS_UNSAVED_CHANGES_PROPERTY)) || (name.equals(View.FILE_PROPERTY))) || (name.equals(View.MULTIPLE_OPEN_ID_PROPERTY))) {
                    updateViewTitle(p, f);
                }
            }
        });
        f.setVisible(true);
        p.start();
    }
}

/**
 * Returns the view component. Eventually wraps it into
 * another component in order to provide additional functionality.
 */
protected Component wrapViewComponent(View p) {
    JComponent c = p.getComponent();
    if ((getModel()) != null) {
        LinkedList<Action> toolBarActions = new LinkedList<Action>();
        int id = 0;
        for (JToolBar tb : new ReversedList<JToolBar>(getModel().createToolBars(this, p))) {
            id++;
            JPanel panel = new JPanel(new BorderLayout());
            panel.add(tb, BorderLayout.NORTH);
            panel.add(c, BorderLayout.CENTER);
            c = panel;
            PreferencesUtil.installToolBarPrefsHandler(prefs, ("toolbar." + id), tb);
            toolBarActions.addFirst(new ToggleVisibleAction(tb, tb.getName()));
        }
        c.putClientProperty("toolBarActions", toolBarActions);
    }
    return c;
}

