private boolean isFocused(Window w) {
    if (w.isFocused())
        return true;

    Window[] ownedWindows = w.getOwnedWindows();
    for (int i = 0; i < (ownedWindows.length); i++) {
        if (isFocused(ownedWindows[i])) {
            return true;
        }
    }
    return false;
}

