    Point p1 = getView().drawingToView(new Point2D.Double(r.x, r.y));
    Point p2 = getView().drawingToView(new Point2D.Double(((r.x) + (r.width)), ((r.y) + (r.height))));
    fireAreaInvalidated(new Rectangle(p1.x, p1.y, ((p2.x) - (p1.x)), ((p2.y) - (p1.y))));
