private void fireAreaInvalidated(BezierPath.Node v) {
    Rectangle2D.Double dr = new Rectangle2D.Double(v.x[0], v.y[0], 0, 0);
    for (int i = 1; i < 3; i++) {
        dr.add(v.x[i], v.y[i]);
