@Override
public void keyPressed(KeyEvent evt) {
    final BezierFigure f = getOwner();
    oldNode = f.getNode(index);
    switch (evt.getKeyCode()) {
        case KeyEvent.VK_UP :
            f.willChange();
            f.setPoint(index, new Point2D.Double(oldNode.x[0], ((oldNode.y[0]) - 1.0)));
            f.changed();
            view.getDrawing().fireUndoableEditHappened(new BezierNodeEdit(f, index, oldNode, f.getNode(index)));
            evt.consume();
            break;
        case KeyEvent.VK_DOWN :
            f.willChange();
            f.setPoint(index, new Point2D.Double(oldNode.x[0], ((oldNode.y[0]) + 1.0)));
            f.changed();
            view.getDrawing().fireUndoableEditHappened(new BezierNodeEdit(f, index, oldNode, f.getNode(index)));
            evt.consume();
            break;
        case KeyEvent.VK_LEFT :
            f.willChange();
            f.setPoint(index, new Point2D.Double(((oldNode.x[0]) - 1.0), oldNode.y[0]));
            f.changed();
            view.getDrawing().fireUndoableEditHappened(new BezierNodeEdit(f, index, oldNode, f.getNode(index)));
            evt.consume();
            break;
        case KeyEvent.VK_RIGHT :
            f.willChange();
            f.setPoint(index, new Point2D.Double(((oldNode.x[0]) + 1.0), oldNode.y[0]));
            f.changed();
            view.getDrawing().fireUndoableEditHappened(new BezierNodeEdit(f, index, oldNode, f.getNode(index)));
            evt.consume();
            break;
        case KeyEvent.VK_DELETE :
        case KeyEvent.VK_BACK_SPACE :
            Rectangle invalidatedArea = getDrawingArea();
            f.willChange();
            final BezierPath.Node removedNode = f.removeNode(index);
            f.changed();
            fireHandleRequestRemove(invalidatedArea);
            fireUndoableEditHappened(new AbstractUndoableEdit() {
                @Override
                public String getPresentationName() {
                    ResourceBundleUtil labels = ResourceBundleUtil.getBundle("org.jhotdraw.draw.Labels");
                    return labels.getString("edit.bezierPath.joinSegment.text");
                }

                @Override
                public void redo() throws CannotRedoException {
                    super.redo();
                    view.removeFromSelection(f);
                    f.willChange();
                    f.removeNode(index);
                    f.changed();
                    view.addToSelection(f);
                }

                @Override
                public void undo() throws CannotUndoException {
                    super.undo();
                    view.removeFromSelection(f);
                    f.willChange();
                    f.addNode(index, removedNode);
                    f.changed();
                    view.addToSelection(f);
                }
            });
            evt.consume();
            break;
    }
}

