public void mousePressed(MouseEvent evt) {
    super.mousePressed(evt);
    getView().clearSelection();
    createdFigure = createFigure();
    Point2D.Double p = constrainPoint(viewToDrawing(anchor));
    anchor.x = evt.getX();
    anchor.y = evt.getY();
    createdFigure.setBounds(p, p);
    getDrawing().add(createdFigure);
}

public void mouseDragged(MouseEvent evt) {
    if ((createdFigure) != null) {
        Point2D.Double p = constrainPoint(new Point(evt.getX(), evt.getY()));
        createdFigure.willChange();
        createdFigure.setBounds(constrainPoint(new Point(anchor.x, anchor.y)), p);
        createdFigure.changed();
    }
}

public void mouseReleased(MouseEvent evt) {
    if ((createdFigure) != null) {
        Rectangle2D.Double bounds = createdFigure.getBounds();
        if (((bounds.width) == 0) && ((bounds.height) == 0)) {
            getDrawing().remove(createdFigure);
            if (isToolDoneAfterCreation()) {
                fireToolDone();
            }
        } else {
            if (((Math.abs(((anchor.x) - (evt.getX())))) < (minimalSizeTreshold.width)) && ((Math.abs(((anchor.y) - (evt.getY())))) < (minimalSizeTreshold.height))) {
                createdFigure.willChange();
                createdFigure.setBounds(constrainPoint(new Point(anchor.x, anchor.y)), constrainPoint(new Point(((anchor.x) + ((int) (Math.max(bounds.width, minimalSize.width)))), ((anchor.y) + ((int) (Math.max(bounds.height, minimalSize.height)))))));
                createdFigure.changed();
            }
            if ((createdFigure) instanceof CompositeFigure) {
                ((CompositeFigure) (createdFigure)).layout();
            }
            final Figure addedFigure = createdFigure;
            final Drawing addedDrawing = getDrawing();
            getDrawing().fireUndoableEditHappened(new AbstractUndoableEdit() {
                public String getPresentationName() {
                    return presentationName;
                }

                public void undo() throws CannotUndoException {
                    super.undo();
                    addedDrawing.remove(addedFigure);
                }

                public void redo() throws CannotRedoException {
                    super.redo();
                    addedDrawing.add(addedFigure);
                }
            });
            creationFinished(createdFigure);
            createdFigure = null;
        }
    } else {
        if (isToolDoneAfterCreation()) {
            fireToolDone();
        }
    }
}

