/**
 * Gets the fill paint for the specified figure based on the attributes
 * FILL_GRADIENT, FILL_OPACITY, FILL_PAINT and the bounds of the figure.
 * Returns null if the figure is not filled.
 */
public static Paint getFillPaint(Figure f) {
    double opacity = ODGAttributeKeys.FILL_OPACITY.get(f);
    if ((ODGAttributeKeys.FILL_GRADIENT.get(f)) != null) {
        return ODGAttributeKeys.FILL_GRADIENT.get(f).getPaint(f, opacity);
    }
    Color color = AttributeKeys.FILL_COLOR.get(f);
    if (color != null) {
        if (opacity != 1) {
            color = new Color((((color.getRGB()) & 16777215) | (((int) (opacity * 255)) << 24)), true);
        }
    }
    return color;
}

/**
 * Gets the stroke paint for the specified figure based on the attributes
 * STROKE_GRADIENT, STROKE_OPACITY, STROKE_PAINT and the bounds of the figure.
 * Returns null if the figure is not filled.
 */
public static Paint getStrokePaint(Figure f) {
    double opacity = ODGAttributeKeys.STROKE_OPACITY.get(f);
    if ((ODGAttributeKeys.STROKE_GRADIENT.get(f)) != null) {
        return ODGAttributeKeys.STROKE_GRADIENT.get(f).getPaint(f, opacity);
    }
    Color color = AttributeKeys.STROKE_COLOR.get(f);
    if (color != null) {
        if (opacity != 1) {
            color = new Color((((color.getRGB()) & 16777215) | (((int) (opacity * 255)) << 24)), true);
        }
    }
    return color;
}

public static Stroke getStroke(Figure f) {
    double strokeWidth = AttributeKeys.STROKE_WIDTH.get(f);
    if (strokeWidth == 0) {
        strokeWidth = 1;
    }
    return new BasicStroke(((float) (strokeWidth)));
}

/**
 * Sets ODG default values.
 */
public static void setDefaults(Figure f) {
    // Fill properties
    AttributeKeys.FILL_COLOR.basicSet(f, Color.black);
    AttributeKeys.WINDING_RULE.basicSet(f, AttributeKeys.WindingRule.NON_ZERO);
    // Stroke properties
    AttributeKeys.STROKE_COLOR.basicSet(f, null);
    AttributeKeys.STROKE_WIDTH.basicSet(f, 1.0);
    AttributeKeys.STROKE_CAP.basicSet(f, BasicStroke.CAP_BUTT);
    AttributeKeys.STROKE_JOIN.basicSet(f, BasicStroke.JOIN_MITER);
    AttributeKeys.STROKE_MITER_LIMIT.basicSet(f, 4.0);
    AttributeKeys.IS_STROKE_MITER_LIMIT_FACTOR.basicSet(f, false);
    AttributeKeys.STROKE_DASHES.basicSet(f, null);
    AttributeKeys.STROKE_DASH_PHASE.basicSet(f, 0.0);
    AttributeKeys.IS_STROKE_DASH_FACTOR.basicSet(f, false);
}

