/**
 * Gets the fill paint for the specified figure based on the attributes
 * FILL_GRADIENT, FILL_OPACITY, FILL_PAINT and the bounds of the figure.
 * Returns null if the figure is not filled.
 */
public static Paint getFillPaint(Figure f) {
    double opacity = SVGAttributeKeys.FILL_OPACITY.get(f);
    if ((SVGAttributeKeys.FILL_GRADIENT.get(f)) != null) {
        return SVGAttributeKeys.FILL_GRADIENT.get(f).getPaint(f, opacity);
    }
    Color color = AttributeKeys.FILL_COLOR.get(f);
    if (color != null) {
        if (opacity != 1) {
            color = new Color((((color.getRGB()) & 16777215) | (((int) (opacity * 255)) << 24)), true);
        }
    }
    return color;
}

/**
 * Gets the stroke paint for the specified figure based on the attributes
 * STROKE_GRADIENT, STROKE_OPACITY, STROKE_PAINT and the bounds of the figure.
 * Returns null if the figure is not filled.
 */
public static Paint getStrokePaint(Figure f) {
    double opacity = SVGAttributeKeys.STROKE_OPACITY.get(f);
    if ((SVGAttributeKeys.STROKE_GRADIENT.get(f)) != null) {
        return SVGAttributeKeys.STROKE_GRADIENT.get(f).getPaint(f, opacity);
    }
    Color color = AttributeKeys.STROKE_COLOR.get(f);
    if (color != null) {
        if (opacity != 1) {
            color = new Color((((color.getRGB()) & 16777215) | (((int) (opacity * 255)) << 24)), true);
        }
    }
    return color;
}

/**
 * Sets SVG default values.
 */
public static void setDefaults(Figure f) {
    // Fill properties
    // http://www.w3.org/TR/SVGMobile12/painting.html#FillProperties
    AttributeKeys.FILL_COLOR.basicSet(f, Color.black);
    AttributeKeys.WINDING_RULE.basicSet(f, AttributeKeys.WindingRule.NON_ZERO);
    // Stroke properties
    // http://www.w3.org/TR/SVGMobile12/painting.html#StrokeProperties
    AttributeKeys.STROKE_COLOR.basicSet(f, null);
    AttributeKeys.STROKE_WIDTH.basicSet(f, 1.0);
    AttributeKeys.STROKE_CAP.basicSet(f, BasicStroke.CAP_BUTT);
    AttributeKeys.STROKE_JOIN.basicSet(f, BasicStroke.JOIN_MITER);
    AttributeKeys.STROKE_MITER_LIMIT.basicSet(f, 4.0);
    AttributeKeys.IS_STROKE_MITER_LIMIT_FACTOR.basicSet(f, false);
    AttributeKeys.STROKE_DASHES.basicSet(f, null);
    AttributeKeys.STROKE_DASH_PHASE.basicSet(f, 0.0);
    AttributeKeys.IS_STROKE_DASH_FACTOR.basicSet(f, false);
}

/**
 * Returns the distance, that a Rectangle needs to grow (or shrink) to
 * make hit detections on a shape as specified by the FILL_UNDER_STROKE and STROKE_POSITION
 * attributes of a figure.
 * The value returned is the number of units that need to be grown (or shrunk)
 * perpendicular to a stroke on an outline of the shape.
 */
public static double getPerpendicularHitGrowth(Figure f) {
    double grow;
    if (((AttributeKeys.STROKE_COLOR.get(f)) == null) && ((SVGAttributeKeys.STROKE_GRADIENT.get(f)) == null)) {
        grow = AttributeKeys.getPerpendicularFillGrowth(f);
    } else {
        double strokeWidth = AttributeKeys.getStrokeTotalWidth(f);
        grow = (AttributeKeys.getPerpendicularDrawGrowth(f)) + (strokeWidth / 2.0);
    }
    return grow;
}

