                return SVGDrawingPanelBeanInfo.iconColor32;
            }
        case BeanInfo.ICON_MONO_16x16 :
            if ((SVGDrawingPanelBeanInfo.iconNameM16) == null)
                return null;
            else {
                if ((SVGDrawingPanelBeanInfo.iconMono16) == null)
                    SVGDrawingPanelBeanInfo.iconMono16 = loadImage(SVGDrawingPanelBeanInfo.iconNameM16);

                return SVGDrawingPanelBeanInfo.iconMono16;
