            Rectangle2D layoutBounds = nextLayout.getBounds();
            paragraphBounds.add(new Rectangle2D.Double(((layoutBounds.getX()) + nextPosition), ((layoutBounds.getY()) + verticalPos), layoutBounds.getWidth(), layoutBounds.getHeight()));
        } 
