    float[] coords = new float[6];
    GeneralPath path = new GeneralPath();
    for (PathIterator i = shape.getPathIterator(t, 1.5F); !(i.isDone()); i.next()) {
        switch (i.currentSegment(coords)) {
            case PathIterator.SEG_MOVETO :
