/* Reads solid color attributes. */
private void readSolidColorElement(IXMLElement elem) throws IOException {
    HashMap<AttributeKey, Object> a = new HashMap<AttributeKey, Object>();
    readCoreAttributes(elem, a);
    // solid-color
    // Value:	 currentColor | <color> | inherit
    // Initial:	 black
    // Applies to:	 solidColor elements
    // Inherited:	 no
    // Percentages:	 N/A
    // Media:	 visual
    // Animatable:	 yes
    // Computed value:  	 Specified <color> value, except inherit
    Color color = toColor(elem, readAttribute(elem, "solid-color", "black"));
    // solid-opacity
    // Value:	<opacity-value> | inherit
    // Initial:	 1
    // Applies to:	 solidColor elements
    // Inherited:	 no
    // Percentages:	 N/A
    // Media:	 visual
    // Animatable:	 yes
    // Computed value:  	 Specified value, except inherit
    double opacity = toDouble(elem, readAttribute(elem, "solid-opacity", "1"), 1, 0, 1);
    if (opacity != 1) {
        color = new Color(((((int) (255 * opacity)) << 24) | (16777215 & (color.getRGB()))), true);
    }
    elementObjects.put(elem, color);
}

/**
 * Reads shape attributes.
 */
private void readShapeAttributes(IXMLElement elem, HashMap<AttributeKey, Object> a) throws IOException {
    Object objectValue;
    String value;
    double doubleValue;
    // color
    // Value:  	<color> | inherit
    // Initial:  	 depends on user agent
    // Applies to:  	None. Indirectly affects other properties via currentColor
    // Inherited:  	 yes
    // Percentages:  	 N/A
    // Media:  	 visual
    // Animatable:  	 yes
    // Computed value:  	 Specified <color> value, except inherit
    // 
    // value = readInheritAttribute(elem, "color", "black");
    // if (DEBUG) System.out.println("color="+value);
    // color-rendering
    // Value:  	 auto | optimizeSpeed | optimizeQuality | inherit
    // Initial:  	 auto
    // Applies to:  	 container elements , graphics elements and animateColor
    // Inherited:  	 yes
    // Percentages:  	 N/A
    // Media:  	 visual
    // Animatable:  	 yes
    // Computed value:  	 Specified value, except inherit
    // 
    // value = readInheritAttribute(elem, "color-rendering", "auto");
    // if (DEBUG) System.out.println("color-rendering="+value);
    // fill
    // Value:  	<paint> | inherit (See Specifying paint)
    // Initial:  	 black
    // Applies to:  	 shapes and text content elements
    // Inherited:  	 yes
    // Percentages:  	 N/A
    // Media:  	 visual
    // Animatable:  	 yes
    // Computed value:  	 "none", system paint, specified <color> value or absolute IRI
    objectValue = toPaint(elem, readInheritColorAttribute(elem, "fill", "black"));
    if (objectValue instanceof Color) {
        AttributeKeys.FILL_COLOR.set(a, ((Color) (objectValue)));
    } else
        if (objectValue instanceof Gradient) {
            SVGAttributeKeys.FILL_GRADIENT.setClone(a, ((Gradient) (objectValue)));
        } else
            if (objectValue == null) {
                AttributeKeys.FILL_COLOR.set(a, null);
            } else {
                AttributeKeys.FILL_COLOR.set(a, null);
                if (SVGInputFormat.DEBUG) {
                    System.out.println(("SVGInputFormat not implemented  fill=" + objectValue));
                }
            }


    // fill-opacity
